-- Wasla — initial schema (Lean MVP scope, forward-compatible with Phases 2–5).
--
-- Conventions
--   * IDs are 64-bit Snowflake values generated by the application (see
--     backend/internal/platform/snowflake). They are NOT sequential, so user and
--     chat IDs cannot be enumerated.
--   * Small integer "enum" columns use the SAME numeric values as the matching
--     protobuf enum in proto/wasla/v1 (e.g. chats.type == wasla.v1.ChatType).
--   * Timestamps are timestamptz (UTC). Unix seconds on the wire.
--   * Hot, high-volume tables (messages, user_updates) are hash-partitioned and
--     carry no foreign keys, so they can later move to ScyllaDB with the same
--     primary keys. Integrity there is enforced by the application.
--
-- Tool: golang-migrate (files NNNN_name.up.sql / NNNN_name.down.sql).

BEGIN;

-- ---------------------------------------------------------------------------
-- Users & accounts
-- ---------------------------------------------------------------------------

CREATE TABLE users (
    id            bigint      PRIMARY KEY,
    phone         text,                                   -- E.164, e.g. +9647701234567; NULL only after deletion
    username      text,                                   -- optional public @handle, case preserved
    first_name    text        NOT NULL,
    last_name     text        NOT NULL DEFAULT '',
    bio           text        NOT NULL DEFAULT '',
    photo_id      bigint,                                 -- current avatar; FK added below
    lang_code     text        NOT NULL DEFAULT 'ar',
    last_seen_at  timestamptz,                            -- persisted on disconnect; live presence is in Redis
    created_at    timestamptz NOT NULL DEFAULT now(),
    updated_at    timestamptz NOT NULL DEFAULT now(),
    banned_at     timestamptz,
    ban_reason    text,
    deleted_at    timestamptz,

    CONSTRAINT users_phone_present   CHECK (deleted_at IS NOT NULL OR phone IS NOT NULL),
    CONSTRAINT users_phone_e164      CHECK (phone IS NULL OR phone ~ '^\+[1-9][0-9]{6,14}$'),
    CONSTRAINT users_username_format CHECK (username IS NULL OR username ~ '^[A-Za-z][A-Za-z0-9_]{4,31}$'),
    CONSTRAINT users_first_name_len  CHECK (char_length(first_name) BETWEEN 1 AND 64),
    CONSTRAINT users_last_name_len   CHECK (char_length(last_name) <= 64),
    CONSTRAINT users_bio_len         CHECK (char_length(bio) <= 140)
);

CREATE UNIQUE INDEX users_phone_uq    ON users (phone) WHERE phone IS NOT NULL;
CREATE UNIQUE INDEX users_username_uq ON users (lower(username)) WHERE username IS NOT NULL;
-- Prefix search for usernames (global search). text_pattern_ops makes LIKE 'abc%' indexable.
CREATE INDEX users_username_prefix_idx ON users (lower(username) text_pattern_ops) WHERE username IS NOT NULL;

-- Per-user update sequence counter ("pts"). Kept out of `users` so that the
-- very frequent increments do not rewrite the wide profile row.
CREATE TABLE user_update_state (
    user_id bigint PRIMARY KEY REFERENCES users (id) ON DELETE CASCADE,
    pts     bigint NOT NULL DEFAULT 0
);

-- Two-step verification. password_hash is an argon2id PHC string.
CREATE TABLE account_passwords (
    user_id                    bigint      PRIMARY KEY REFERENCES users (id) ON DELETE CASCADE,
    password_hash              text        NOT NULL,
    hint                       text        NOT NULL DEFAULT '',
    recovery_email             text,
    recovery_email_verified_at timestamptz,
    updated_at                 timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT account_passwords_hint_len CHECK (char_length(hint) <= 64)
);

-- One row per logged-in device. The client holds a 256-bit random token; only
-- its SHA-256 is stored.
CREATE TABLE sessions (
    id                    bigint      PRIMARY KEY,
    user_id               bigint      NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    token_hash            bytea       NOT NULL,
    platform              smallint    NOT NULL,           -- wasla.v1.Platform
    device_model          text        NOT NULL DEFAULT '',
    os_version            text        NOT NULL DEFAULT '',
    app_version           text        NOT NULL DEFAULT '',
    ip                    inet,
    country_code          text,                           -- ISO 3166-1 alpha-2, from GeoIP
    push_provider         smallint,                       -- wasla.v1.PushProvider
    push_token            text,
    push_token_updated_at timestamptz,
    created_at            timestamptz NOT NULL DEFAULT now(),
    last_active_at        timestamptz NOT NULL DEFAULT now(),
    revoked_at            timestamptz,

    CONSTRAINT sessions_token_hash_len CHECK (octet_length(token_hash) = 32),
    CONSTRAINT sessions_push_pair      CHECK ((push_provider IS NULL) = (push_token IS NULL))
);

CREATE UNIQUE INDEX sessions_token_uq    ON sessions (token_hash);
CREATE INDEX        sessions_user_active ON sessions (user_id) WHERE revoked_at IS NULL;
-- A device push token belongs to at most one live session (re-login moves it).
CREATE UNIQUE INDEX sessions_push_token_uq ON sessions (push_provider, push_token)
    WHERE revoked_at IS NULL AND push_token IS NOT NULL;

-- Audit log of OTP sends, for SMS cost tracking and SMS-pumping fraud
-- detection. The codes themselves live only in Redis (hashed, with TTL).
CREATE TABLE otp_requests (
    id          bigint      GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    phone       text        NOT NULL,
    ip          inet,
    channel     smallint    NOT NULL,                     -- wasla.v1.CodeDelivery
    provider    text        NOT NULL DEFAULT '',          -- SMS aggregator used
    status      smallint    NOT NULL,                     -- 1 sent, 2 verified, 3 failed, 4 blocked_by_antifraud
    cost_usd    numeric(10, 5),
    created_at  timestamptz NOT NULL DEFAULT now(),
    verified_at timestamptz
);

CREATE INDEX otp_requests_phone_idx   ON otp_requests (phone, created_at DESC);
CREATE INDEX otp_requests_created_idx ON otp_requests (created_at);

-- ---------------------------------------------------------------------------
-- Privacy, blocking, contacts
-- ---------------------------------------------------------------------------

-- A missing row means "use the default" (defaults are defined in code and in
-- docs/02-data-model.md).
CREATE TABLE privacy_rules (
    user_id bigint   NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    key     smallint NOT NULL,                            -- wasla.v1.PrivacyKey
    rule    smallint NOT NULL,                            -- wasla.v1.PrivacyRule
    PRIMARY KEY (user_id, key)
);

CREATE TABLE privacy_exceptions (
    user_id        bigint   NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    key            smallint NOT NULL,
    target_user_id bigint   NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    allow          boolean  NOT NULL,                     -- true: always allow, false: always deny
    PRIMARY KEY (user_id, key, target_user_id)
);

CREATE TABLE user_blocks (
    user_id         bigint      NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    blocked_user_id bigint      NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    created_at      timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (user_id, blocked_user_id),
    CONSTRAINT user_blocks_not_self CHECK (user_id <> blocked_user_id)
);

CREATE INDEX user_blocks_reverse_idx ON user_blocks (blocked_user_id);

-- Phone-book entries uploaded by a user. contact_user_id is resolved when the
-- phone belongs to (or later joins) Wasla.
CREATE TABLE contacts (
    owner_id        bigint      NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    phone           text        NOT NULL,
    first_name      text        NOT NULL DEFAULT '',
    last_name       text        NOT NULL DEFAULT '',
    contact_user_id bigint      REFERENCES users (id) ON DELETE SET NULL,
    created_at      timestamptz NOT NULL DEFAULT now(),
    updated_at      timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (owner_id, phone),
    CONSTRAINT contacts_phone_e164 CHECK (phone ~ '^\+[1-9][0-9]{6,14}$')
);

CREATE INDEX contacts_phone_idx        ON contacts (phone);                -- "who saved this number" on sign-up
CREATE INDEX contacts_contact_user_idx ON contacts (contact_user_id) WHERE contact_user_id IS NOT NULL;

-- ---------------------------------------------------------------------------
-- Media
-- ---------------------------------------------------------------------------

-- Bytes live in S3-compatible object storage; this is the metadata.
CREATE TABLE media_files (
    id          bigint      PRIMARY KEY,
    owner_id    bigint      NOT NULL REFERENCES users (id),
    kind        smallint    NOT NULL,                     -- wasla.v1.MediaKind
    mime_type   text        NOT NULL,
    size_bytes  bigint      NOT NULL,
    sha256      bytea,
    storage_key text        NOT NULL,
    file_name   text        NOT NULL DEFAULT '',
    width       integer,
    height      integer,
    duration_ms integer,
    thumbhash   bytea,                                    -- ~25-byte placeholder, sent inline with messages
    waveform    bytea,                                    -- voice messages: 5-bit samples, packed
    variants    jsonb       NOT NULL DEFAULT '[]',        -- [{"type":"thumb_m","key":"...","w":320,"h":240,"size":12345}]
    status      smallint    NOT NULL DEFAULT 1,           -- 1 uploading, 2 processing, 3 ready, 4 failed
    created_at  timestamptz NOT NULL DEFAULT now(),
    ready_at    timestamptz,

    CONSTRAINT media_files_size      CHECK (size_bytes BETWEEN 0 AND 2147483648),   -- 2 GiB
    CONSTRAINT media_files_sha256    CHECK (sha256 IS NULL OR octet_length(sha256) = 32),
    CONSTRAINT media_files_thumbhash CHECK (thumbhash IS NULL OR octet_length(thumbhash) <= 64)
);

CREATE INDEX media_files_owner_idx   ON media_files (owner_id, created_at DESC);
CREATE INDEX media_files_pending_idx ON media_files (created_at) WHERE status IN (1, 2);   -- cleanup job
CREATE INDEX media_files_sha_idx     ON media_files (sha256, size_bytes) WHERE status = 3;  -- server-side dedup

ALTER TABLE users
    ADD CONSTRAINT users_photo_fk FOREIGN KEY (photo_id) REFERENCES media_files (id) ON DELETE SET NULL;

CREATE TABLE profile_photos (
    user_id    bigint      NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    media_id   bigint      NOT NULL REFERENCES media_files (id) ON DELETE CASCADE,
    created_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (user_id, media_id)
);

-- ---------------------------------------------------------------------------
-- Chats
-- ---------------------------------------------------------------------------

CREATE TABLE chats (
    id                  bigint      PRIMARY KEY,
    type                smallint    NOT NULL,             -- wasla.v1.ChatType: 1 private, 2 saved, 3 group (4 supergroup, 5 channel reserved)
    title               text        NOT NULL DEFAULT '',
    about               text        NOT NULL DEFAULT '',
    photo_id            bigint      REFERENCES media_files (id) ON DELETE SET NULL,
    creator_id          bigint      REFERENCES users (id) ON DELETE SET NULL,
    member_count        integer     NOT NULL DEFAULT 0,
    default_permissions bigint      NOT NULL DEFAULT 31,  -- wasla.v1.MemberPermission bitmask; 31 = all
    last_seq            bigint      NOT NULL DEFAULT 0,   -- highest message seq allocated in this chat
    last_message_at     timestamptz,
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now(),
    deleted_at          timestamptz,

    CONSTRAINT chats_type_valid  CHECK (type BETWEEN 1 AND 5),
    CONSTRAINT chats_group_title CHECK (type IN (1, 2) OR char_length(title) BETWEEN 1 AND 128),
    CONSTRAINT chats_about_len   CHECK (char_length(about) <= 255)
);

-- Maps a pair of users to their private chat. (u, u) is that user's Saved Messages.
CREATE TABLE private_chat_pairs (
    user_low  bigint NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    user_high bigint NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    chat_id   bigint NOT NULL REFERENCES chats (id) ON DELETE CASCADE,
    PRIMARY KEY (user_low, user_high),
    CONSTRAINT private_chat_pairs_order CHECK (user_low <= user_high)
);

CREATE UNIQUE INDEX private_chat_pairs_chat_uq ON private_chat_pairs (chat_id);

-- Membership + the per-user dialog state for that chat.
CREATE TABLE chat_members (
    chat_id         bigint      NOT NULL REFERENCES chats (id) ON DELETE CASCADE,
    user_id         bigint      NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    role            smallint    NOT NULL DEFAULT 1,       -- wasla.v1.ChatMemberRole: 1 member, 2 admin, 3 owner
    admin_rights    bigint      NOT NULL DEFAULT 0,       -- wasla.v1.AdminRight bitmask
    invited_by      bigint,
    joined_at       timestamptz NOT NULL DEFAULT now(),
    read_inbox_seq  bigint      NOT NULL DEFAULT 0,       -- this user has read up to here
    read_outbox_seq bigint      NOT NULL DEFAULT 0,       -- someone else has read this user's messages up to here (drives ✓✓)
    cleared_seq     bigint      NOT NULL DEFAULT 0,       -- "clear history" for this user only
    pinned_rank     integer,                              -- NULL = not pinned; lower = higher in the list
    archived        boolean     NOT NULL DEFAULT false,
    muted_until     timestamptz,
    PRIMARY KEY (chat_id, user_id),
    CONSTRAINT chat_members_role_valid CHECK (role BETWEEN 1 AND 3)
);

CREATE INDEX chat_members_user_idx ON chat_members (user_id) INCLUDE (archived, pinned_rank);

CREATE TABLE chat_invites (
    code        text        PRIMARY KEY,                  -- 16 URL-safe random characters
    chat_id     bigint      NOT NULL REFERENCES chats (id) ON DELETE CASCADE,
    created_by  bigint      NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    title       text        NOT NULL DEFAULT '',
    expires_at  timestamptz,
    usage_limit integer,
    usage_count integer     NOT NULL DEFAULT 0,
    revoked_at  timestamptz,
    created_at  timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT chat_invites_usage CHECK (usage_limit IS NULL OR usage_limit > 0)
);

CREATE INDEX chat_invites_chat_idx ON chat_invites (chat_id);

-- ---------------------------------------------------------------------------
-- Messages (hot path)
-- ---------------------------------------------------------------------------

-- A message is addressed by (chat_id, seq). seq is allocated per chat with
-- `UPDATE chats SET last_seq = last_seq + 1 ... RETURNING last_seq` inside the
-- send transaction, so it is gap-free in practice and unread counts are cheap.
CREATE TABLE messages (
    chat_id      bigint      NOT NULL,
    seq          bigint      NOT NULL,
    sender_id    bigint      NOT NULL,
    random_id    bigint      NOT NULL,                    -- client idempotency key: a retried send returns the original
    kind         smallint    NOT NULL,                    -- MessageContent oneof field number (1 text, 2 photo, ...)
    text         text        NOT NULL DEFAULT '',         -- body or caption
    entities     jsonb,                                   -- [{"t":1,"o":0,"l":5}] offsets in UTF-16 code units
    media_id     bigint,
    reply_to_seq bigint,
    fwd          jsonb,                                   -- {"from_user_id":..,"from_name":"..","date":..,"from_chat_id":..,"from_seq":..}
    extra        jsonb,                                   -- location / contact / service-action payloads
    created_at   timestamptz NOT NULL DEFAULT now(),
    edited_at    timestamptz,
    deleted_at   timestamptz,                             -- "delete for everyone" tombstone; content is wiped

    PRIMARY KEY (chat_id, seq),
    CONSTRAINT messages_random_uq UNIQUE (chat_id, sender_id, random_id),
    CONSTRAINT messages_text_len  CHECK (char_length(text) <= 4096)
) PARTITION BY HASH (chat_id);

DO $$
BEGIN
    FOR i IN 0..15 LOOP
        EXECUTE format(
            'CREATE TABLE messages_p%s PARTITION OF messages FOR VALUES WITH (MODULUS 16, REMAINDER %s)',
            lpad(i::text, 2, '0'), i);
    END LOOP;
END $$;

-- "Shared media" tab and media access checks.
CREATE INDEX messages_chat_kind_idx ON messages (chat_id, kind, seq DESC) WHERE deleted_at IS NULL;

-- "Delete for me".
CREATE TABLE message_hides (
    user_id bigint NOT NULL,
    chat_id bigint NOT NULL,
    seq     bigint NOT NULL,
    PRIMARY KEY (user_id, chat_id, seq)
);

CREATE TABLE chat_pins (
    chat_id   bigint      NOT NULL REFERENCES chats (id) ON DELETE CASCADE,
    seq       bigint      NOT NULL,
    pinned_by bigint      REFERENCES users (id) ON DELETE SET NULL,
    pinned_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (chat_id, seq)
);

-- ---------------------------------------------------------------------------
-- Per-user update log (multi-device sync)
-- ---------------------------------------------------------------------------

-- Every state change a user must see appends one row with the user's next pts.
-- Devices replay the log from their last known pts (UpdatesService.GetDifference).
-- Retention: 30 days or the last 10,000 rows per user, whichever is larger;
-- older clients get `too_long` and resync dialogs.
CREATE TABLE user_updates (
    user_id    bigint      NOT NULL,
    pts        bigint      NOT NULL,
    kind       smallint    NOT NULL,                      -- wasla.v1.Update oneof field number
    chat_id    bigint,
    payload    bytea       NOT NULL,                      -- serialized wasla.v1.Update
    created_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (user_id, pts)
) PARTITION BY HASH (user_id);

DO $$
BEGIN
    FOR i IN 0..15 LOOP
        EXECUTE format(
            'CREATE TABLE user_updates_p%s PARTITION OF user_updates FOR VALUES WITH (MODULUS 16, REMAINDER %s)',
            lpad(i::text, 2, '0'), i);
    END LOOP;
END $$;

CREATE INDEX user_updates_created_idx ON user_updates (created_at);

-- ---------------------------------------------------------------------------
-- Moderation (report/block is required for store approval and for CMC)
-- ---------------------------------------------------------------------------

CREATE TABLE staff_users (
    id            bigint      GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    email         text        NOT NULL,
    display_name  text        NOT NULL,
    password_hash text        NOT NULL,                   -- argon2id
    totp_secret   bytea,                                  -- mandatory before first login (enforced in app)
    role          smallint    NOT NULL,                   -- 1 moderator, 2 senior moderator, 3 admin
    created_at    timestamptz NOT NULL DEFAULT now(),
    disabled_at   timestamptz
);

CREATE UNIQUE INDEX staff_users_email_uq ON staff_users (lower(email));

CREATE TABLE reports (
    id             bigint      GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    reporter_id    bigint      NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    target_user_id bigint      REFERENCES users (id) ON DELETE SET NULL,
    chat_id        bigint      REFERENCES chats (id) ON DELETE SET NULL,
    message_seqs   bigint[]    NOT NULL DEFAULT '{}',
    reason         smallint    NOT NULL,                  -- wasla.v1.ReportReason
    comment        text        NOT NULL DEFAULT '',
    evidence       jsonb,                                 -- snapshot of reported messages, so later deletion keeps the evidence
    status         smallint    NOT NULL DEFAULT 1,        -- 1 open, 2 actioned, 3 dismissed
    handled_by     bigint      REFERENCES staff_users (id),
    handled_at     timestamptz,
    resolution     text,
    created_at     timestamptz NOT NULL DEFAULT now(),

    CONSTRAINT reports_has_target  CHECK (target_user_id IS NOT NULL OR chat_id IS NOT NULL),
    CONSTRAINT reports_comment_len CHECK (char_length(comment) <= 512)
);

CREATE INDEX reports_open_idx   ON reports (created_at) WHERE status = 1;
CREATE INDEX reports_target_idx ON reports (target_user_id) WHERE target_user_id IS NOT NULL;

-- Append-only audit trail of everything staff do.
CREATE TABLE moderation_actions (
    id             bigint      GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    staff_id       bigint      NOT NULL REFERENCES staff_users (id),
    report_id      bigint      REFERENCES reports (id),
    target_user_id bigint      REFERENCES users (id) ON DELETE SET NULL,
    chat_id        bigint      REFERENCES chats (id) ON DELETE SET NULL,
    action         smallint    NOT NULL,                  -- 1 warn, 2 delete_content, 3 ban_user, 4 unban_user, 5 delete_chat
    reason         text        NOT NULL,
    expires_at     timestamptz,                           -- temporary bans
    created_at     timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX moderation_actions_target_idx ON moderation_actions (target_user_id, created_at DESC);

COMMIT;
